def retry(max_attempts: int = 3):
    """Decorator that retries a function up to max_attempts times on Exception."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_err = None
            for _ in range(max_attempts):
                try:
